// Tri-series Tournament Algorithm — three sides, double round-robin, final.
//
// The classic ODI tri-series shape: exactly three teams, each pair plays
// twice (6 group games total), then the top two by standings meet in a
// final. The final itself is generated by the existing playoff engine
// (a "final-only" config) — this module only builds the group stage.

import type { Match } from "../types";

export interface TriSeriesOptions {
  teams: [string, string, string];
  maxOvers: number;
  maxWickets: number;
}

/**
 * Fixed play order for the two legs, each team's two meetings with the same
 * opponent spaced 3 slots apart: {A,B} at 1 & 4, {B,C} at 2 & 5, {C,A} at 3 & 6.
 */
export function generateTriSeriesMatches(options: TriSeriesOptions): Match[] {
  const { teams, maxOvers, maxWickets } = options;
  const [a, b, c] = teams;

  const pairs: [string, string][] = [
    [a, b],
    [b, c],
    [c, a],
    [b, a],
    [c, b],
    [a, c],
  ];

  return pairs.map(([team1, team2], i) => ({
    id: `T-${(i + 1).toString().padStart(3, "0")}`,
    team1,
    team2,
    round: i + 1,
    status: "scheduled" as const,
    overs: maxOvers,
    maxWickets,
  }));
}

export function validateTriSeriesTeams(teams: string[]): {
  valid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  if (teams.length !== 3) {
    errors.push("A tri-series is between exactly 3 sides");
  }

  const uniqueTeams = new Set(teams);
  if (uniqueTeams.size !== teams.length) {
    errors.push("Duplicate team names are not allowed");
  }

  const emptyNames = teams.filter((team) => !team.trim());
  if (emptyNames.length > 0) {
    errors.push("Empty team names are not allowed");
  }

  return { valid: errors.length === 0, errors };
}
